sir 0.3

software DualTokenDesk {
  metadata {
    displayName "Dual Token Desk";
    namespace "example.dualtoken";
  }
  target {
    language java 21;
    framework spring_boot;
    persistence mybatis_plus;
    database mysql;
    build maven;
    interface rest;
  }
  sources { }
  imports { }
  declarations {
    entity User persistent {
      identity id: Id generated auto;
      field name: Name unique;
      field passwordHash: Secret;
    }
    entity Note persistent {
      identity id: Id generated auto;
      field author: Ref<User>;
      field text: Text;
    }
    entity AccessToken persistent {
      identity id: Token generated uuid;
      field owner: Ref<User>;
      field expiresAt: Moment;
      credential subject owner expires expiresAt;
    }
    entity RefreshToken persistent {
      identity id: Token generated uuid;
      field owner: Ref<User>;
      field used: Flag;
      field expiresAt: Moment;
    }
    entity TokenPair persistent {
      identity id: Id generated auto;
      field accessToken: Token;
      field accessExpiresAt: Moment;
      field refreshToken: Token;
      field refreshExpiresAt: Moment;
    }
    view NoteView from Note {
      field id: Id;
      field text: Text;
    }
    input NoteInput {
      field text: Text where notBlank;
    }
    view UserView from User {
      field id: Id;
      field name: Text;
    }
    view TokenPairView from TokenPair {
      field accessToken: Token;
      field accessExpiresAt: Moment;
      field refreshToken: Token;
      field refreshExpiresAt: Moment;
    }
    input UserRef {
      field id: Id;
    }
    input LoginInput {
      field name: Text;
      field password: Text;
    }
    input RefreshInput {
      field refreshToken: Token;
    }
    input LogoutInput {
      field refreshToken: Token;
    }
    error UserNotFound http 404;
    error BadLogin http 401;
    error InvalidRefreshToken http 401;
    error ExpiredRefreshToken http 401;
    input RegisterInput {
      field name: Text;
      field password: Text;
    }
    capability GetUser {
      input UserRef;
      output UserView;
      fails UserNotFound;
      requires readonly;
      expose query;
      workflow {
        load User by input.id as user else UserNotFound;
        return user;
      }
    }
    capability Register {
      input RegisterInput;
      output UserView;
      requires atomic;
      expose command;
      workflow {
        create User as user {
          name: input.name;
          passwordHash: input.password;
        }
        persist user;
        return user;
      }
    }
    capability PostNote {
      actor Ref<User>;
      input NoteInput;
      output NoteView;
      requires authenticated;
      requires atomic;
      expose command;
      workflow {
        create Note as note {
          author: actor;
          text: input.text;
        }
        persist note;
        return note;
      }
    }
    capability Login {
      input LoginInput;
      output TokenPairView;
      fails BadLogin;
      requires atomic;
      expose command;
      workflow {
        load User by name: input.name as holder else BadLogin;
        validate holder.passwordHash matches input.password else BadLogin;
        create AccessToken as access {
          owner: holder;
          expiresAt: now() + 15 minutes;
        }
        create RefreshToken as refresh {
          owner: holder;
          used: false;
          expiresAt: now() + 7 days;
        }
        create TokenPair as pair {
          accessToken: access;
          accessExpiresAt: access.expiresAt;
          refreshToken: refresh;
          refreshExpiresAt: refresh.expiresAt;
        }
        persist access;
        persist refresh;
        persist pair;
        return pair;
      }
    }
    capability Refresh {
      input RefreshInput;
      output TokenPairView;
      fails InvalidRefreshToken;
      fails ExpiredRefreshToken;
      requires atomic;
      expose command;
      workflow {
        load RefreshToken by input.refreshToken as old else InvalidRefreshToken;
        validate old.expiresAt > now() else ExpiredRefreshToken;
        update old when old.used == false and old.expiresAt > now() else InvalidRefreshToken {
          used: true;
        }
        load User by old.owner as holder else InvalidRefreshToken;
        create AccessToken as access {
          owner: holder;
          expiresAt: now() + 15 minutes;
        }
        create RefreshToken as refresh {
          owner: holder;
          used: false;
          expiresAt: now() + 7 days;
        }
        create TokenPair as pair {
          accessToken: access;
          accessExpiresAt: access.expiresAt;
          refreshToken: refresh;
          refreshExpiresAt: refresh.expiresAt;
        }
        persist old;
        persist access;
        persist refresh;
        persist pair;
        return pair;
      }
    }
    capability Logout {
      input LogoutInput;
      output TokenPairView;
      fails InvalidRefreshToken;
      requires atomic;
      expose command;
      workflow {
        load RefreshToken by input.refreshToken as old else InvalidRefreshToken;
        update old when old.used == false else InvalidRefreshToken {
          used: true;
        }
        persist old;
        load TokenPair by accessToken: old.id as pair else InvalidRefreshToken;
        return pair;
      }
    }
  }
}
